 "content": "def transform(grid):
    # Count the two orientations of the small 3-cell bar-plus-stem motifs.
    # Horizontal motif: three across with a stem below the middle (or above).
    # Vertical counterpart: three down with a side stem; outputs encode counts.
    h = len(grid); w = len(grid[0])
    shapes = [
        {(0,0),(0,1),(0,2),(1,1)},
        {(1,0),(1,1),(1,2),(0,1)},
        {(0,0),(1,0),(2,0),(1,1)},
        {(0,1),(1,1),(2,1),(1,0)},
    ]
    found=[]
    for r in range(h):
        for c in range(w):
            for s in shapes:
                pts={(r+dr,c+dc) for dr,dc in s}
                if all(0 <= y < h and 0 <= x < w and grid[y][x] == 2 for y,x in pts):
                    found.append((r,c,s))
    # Encode detected objects by their relative left/right and orientation in 3x6.
    out=[[0]*6 for _ in range(3)]
    for r,c,s in found:
        # each motif's bounding-box center locates its output column group
        cx=c+1
        col=0 if cx < w/2 else 3
        # horizontal bars -> 3 marks on top/bottom; vertical -> central mark
        is_h=any((0,0) in s and (0,2) in s)
        if is_h:
            out[0][col]=3 if col==0 else 1
            out[2][col+2]=3 if col==0 else 1
        else:
            out[1][col+1]=3 if col==0 else 1
    return out
