    # Each 2-valued cell is a mark in a 3x3 logical tile; reduce each
    # repeated motif family into the corresponding output indicator.
    h, w = len(grid), len(grid[0])
    out = [[0] * 6 for _ in range(3)]
    # Motifs are four-cell T tetrominoes. The output summarizes which
    # corner-directed T forms occur in the left and right halves.
    motifs = [
        ({(0,0),(0,1),(0,2),(1,1)}, 'top'),
        ({(1,0),(1,1),(1,2),(0,1)}, 'bottom'),
        ({(0,0),(1,0),(2,0),(1,1)}, 'left'),
        ({(0,1),(1,1),(2,1),(1,0)}, 'right'),
    ]
    seen=set()
    for r in range(h):
        for c in range(w):
            for shape, kind in motifs:
                pts={(r+dr,c+dc) for dr,dc in shape}
                if not all(0 <= y < h and 0 <= x < w and grid[y][x] == 2 for y,x in pts):
                    continue
                if any((y,x) in seen for y,x in pts):
                    continue
                seen.update(pts)
                side = 0 if c + 1 < w/2 else 1
                val = 3 if side == 0 else 1
                if kind == 'top':
                    out[0][side*3] = val
                elif kind == 'bottom':
                    out[2][side*3+2] = val
                else:
                    out[1][side*3+(1 if kind == 'left' else 2)] = val
    return out
